<?php
declare(strict_types=1);
require __DIR__.'/includes/ui.php';
$user=msw_require_user();$uid=(int)$user['id'];msw_fob_resolve_due_dispatches($uid,8);msw_bot_simulation_pulse(null,10);
$membership=msw_fob_membership($uid);if(!$membership)msw_redirect('fob_globe.php');
$requestedWorld=(int)($_GET['world']??0);$worldId=$requestedWorld>0?$requestedWorld:(int)$membership['world_id'];$world=msw_fob_world_row($worldId);if(!$world){http_response_code(404);exit('FOB world unavailable.');}
$isHome=$worldId===(int)$membership['world_id'];$biome=msw_fob_biome_catalog()[(string)$world['biome_key']]??null;if(!$biome)throw new RuntimeException('FOB biome unavailable.');
$skins=msw_fob_skin_catalog();$members=msw_fob_world_members($worldId);$population=count($members);$protected=!empty($user['fob_protection_until'])&&strtotime((string)$user['fob_protection_until'])>time();$pending=msw_one("SELECT COUNT(*) c FROM fob_strike_dispatches WHERE attacker_user_id=? AND result='pending'",'i',[$uid]);
$centerX=$isHome?(int)$membership['x']:1000;$centerY=$isHome?(int)$membership['y']:1000;
msw_header($isHome?'FOB Overview World':'Remote FOB Invasion Shard','fob.php');msw_alert(msw_flash());msw_resource_strip($uid);
?>
