<div class="fob-world-toolbar"><span class="badge">INSTANCE <?=msw_e(msw_fob_world_name($world))?></span><span class="badge"><?=number_format($population)?> / <?=number_format((int)$world['capacity'])?> FOBs</span><span class="badge"><?=$protected?'YOUR HOME FOB PROTECTED':'YOUR HOME FOB OPEN'?></span><span class="badge"><?=intval($pending['c']??0)?> STAFF STRIKES ACTIVE</span><a class="btn" href="<?=msw_e(msw_url('fob.php'))?>">Command Centre</a><a class="btn secondary" href="<?=msw_e(msw_url('fob_globe.php'))?>">Global Earth</a><a class="btn secondary" href="<?=msw_e(msw_url('fob_infiltration.php?world='.$worldId))?>">Target List</a><a class="btn secondary" href="<?=msw_e(msw_url('fob_dispatch.php'))?>">Strike Ledger</a><?php if(!$isHome):?><a class="btn secondary" href="<?=msw_e(msw_url('fob_world.php'))?>">Home Shard</a><?php endif;?></div>
<section class="fob-world-console"><div class="fob-world-console-head"><div><small>NATIVE 2000 × 2000 OVERVIEW</small><strong><?=msw_e($biome['name'])?> World · Shard <?=str_pad((string)(int)$world['shard_index'],3,'0',STR_PAD_LEFT)?></strong></div><div class="warzone-readout"><span><?=$isHome?'Persistent world slot '.(intval($membership['slot_index'])+1):'Cross-shard reconnaissance'?></span><b><?=$isHome?'HOME PLACEMENT LOCKED':'GLOBAL INVASION ACCESS'?></b></div></div>
<div class="fob-world-viewport" data-fob-world-viewport data-own-x="<?=$centerX?>" data-own-y="<?=$centerY?>"><div class="fob-world-map" style="width:<?=intval($biome['w'])?>px;height:<?=intval($biome['h'])?>px"><img class="fob-overview-level" src="<?=msw_e(msw_url($biome['image']))?>" width="<?=intval($biome['w'])?>" height="<?=intval($biome['h'])?>" alt="<?=msw_e($biome['name'])?> FOB overview">
<?php foreach($members as $member):$skin=$skins[$member['skin_key']]??null;if(!$skin)continue;$isMe=(int)$member['id']===$uid;$isProtected=!empty($member['fob_protection_until'])&&strtotime((string)$member['fob_protection_until'])>time();$tag=(int)$member['is_bot']===1?'AI':'PLAYER';?>
