<img src="<?=msw_e(msw_url($skin['icon']))?>" width="256" height="171" alt=""><span><b><?=msw_e($isMe?'YOUR FOB':$member['username'])?></b><small><?=$isMe?'COMMAND NODE':$tag.' · '.msw_e($member['base_grade']).($isProtected?' · PROTECTED':'')?></small></span><?=$isMe?'</div>':'</a>'?><?php endforeach;?>
</div></div><div class="warzone-scroll-hint"><span>◀</span><span>Native overview · <?=$isHome?'camera centers on your persistent FOB':'remote shard reconnaissance'?> · scroll to survey rivals</span><span>▶</span></div></section>
